INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-beki-1', 'sent-ex-beki-1', 'en', 'You ought to keep your promises.', 'authored'),
  ('st-ex-beki-2', 'sent-ex-beki-2', 'en', 'I should study more.', 'authored'),
  ('st-ex-beki-3', 'sent-ex-beki-3', 'en', 'You ought to talk it over with the teacher.', 'authored'),
  ('st-ex-beki-4', 'sent-ex-beki-4', 'en', 'If you have a temperature you ought to see a doctor.', 'authored'),
  ('st-ex-hazuganai-1', 'sent-ex-hazuganai-1', 'en', 'There is no way the teacher does not know.', 'authored'),
  ('st-ex-hazuganai-2', 'sent-ex-hazuganai-2', 'en', 'That shop cannot possibly be closed.', 'authored'),
  ('st-ex-hazuganai-3', 'sent-ex-hazuganai-3', 'en', 'There is no way my older brother would forget a promise.', 'authored'),
  ('st-ex-hazuganai-4', 'sent-ex-hazuganai-4', 'en', 'He practised every day; there is no way he loses.', 'authored'),
  ('st-ex-wakeda-1', 'sent-ex-wakeda-1', 'en', 'He practised every day, so of course he got good at it.', 'authored'),
  ('st-ex-wakeda-2', 'sent-ex-wakeda-2', 'en', 'He lived there a long time, so naturally he is used to life in Japan.', 'authored'),
  ('st-ex-wakeda-3', 'sent-ex-wakeda-3', 'en', 'The train stopped, so that is why we were late.', 'authored'),
  ('st-ex-wakeda-4', 'sent-ex-wakeda-4', 'en', 'It snowed, so no wonder it is cold.', 'authored'),
  ('st-ex-wakedewa-1', 'sent-ex-wakedewa-1', 'en', 'It is not that I dislike it.', 'authored'),
  ('st-ex-wakedewa-2', 'sent-ex-wakedewa-2', 'en', 'It is not as if I understand all of it.', 'authored'),
  ('st-ex-wakedewa-3', 'sent-ex-wakedewa-3', 'en', 'It is not that I go every day.', 'authored'),
  ('st-ex-wakedewa-4', 'sent-ex-wakedewa-4', 'en', 'It is not that I am refusing to buy it because it is expensive.', 'authored'),
  ('st-ex-monoda-1', 'sent-ex-monoda-1', 'en', 'When I was a child I used to swim in the river a lot.', 'authored'),
  ('st-ex-monoda-2', 'sent-ex-monoda-2', 'en', 'How quickly time passes.', 'authored'),
  ('st-ex-monoda-3', 'sent-ex-monoda-3', 'en', 'You should listen to what your parents tell you.', 'authored'),
  ('st-ex-monoda-4', 'sent-ex-monoda-4', 'en', 'I used to read a lot of books in the old days.', 'authored'),
  ('st-ex-kotonisuru-1', 'sent-ex-kotonisuru-1', 'en', 'I have decided to run every morning.', 'authored'),
  ('st-ex-kotonisuru-2', 'sent-ex-kotonisuru-2', 'en', 'I decided to keep a diary every day.', 'authored'),
  ('st-ex-kotonisuru-3', 'sent-ex-kotonisuru-3', 'en', 'I have decided to go to Japan next year.', 'authored'),
  ('st-ex-kotonisuru-4', 'sent-ex-kotonisuru-4', 'en', 'I make it a rule not to eat sweet things.', 'authored'),
  ('st-ex-kotoninaru-1', 'sent-ex-kotoninaru-1', 'en', 'It has been arranged that I will work at a new company from next month.', 'authored'),
  ('st-ex-kotoninaru-2', 'sent-ex-kotoninaru-2', 'en', 'It has been decided that the exam will be held next week.', 'authored'),
  ('st-ex-kotoninaru-3', 'sent-ex-kotoninaru-3', 'en', 'It has been settled that my older brother is getting married.', 'authored'),
  ('st-ex-kotoninaru-4', 'sent-ex-kotoninaru-4', 'en', 'It has been decided that the shop closes from tomorrow.', 'authored'),
  ('st-ex-tatokoroda-1', 'sent-ex-tatokoroda-1', 'en', 'I have just this minute arrived at the station.', 'authored'),
  ('st-ex-tatokoroda-2', 'sent-ex-tatokoroda-2', 'en', 'The bus has just left.', 'authored'),
  ('st-ex-tatokoroda-3', 'sent-ex-tatokoroda-3', 'en', 'I have just been speaking to the teacher.', 'authored'),
  ('st-ex-tatokoroda-4', 'sent-ex-tatokoroda-4', 'en', 'I have just rung my mother.', 'authored'),
  ('st-ex-uchini-1', 'sent-ex-uchini-1', 'en', 'I want to go abroad while I am still young.', 'authored'),
  ('st-ex-uchini-2', 'sent-ex-uchini-2', 'en', 'Let us go home while it is still light.', 'authored'),
  ('st-ex-uchini-3', 'sent-ex-uchini-3', 'en', 'I will make a note of it before I forget.', 'authored'),
  ('st-ex-uchini-4', 'sent-ex-uchini-4', 'en', 'Please eat it while it is hot.', 'authored'),
  ('st-ex-tabini-1', 'sent-ex-tabini-1', 'en', 'Every time I look at that photograph I remember my childhood.', 'authored'),
  ('st-ex-tabini-2', 'sent-ex-tabini-2', 'en', 'Every time I go to Japan I buy souvenirs.', 'authored'),
  ('st-ex-tabini-3', 'sent-ex-tabini-3', 'en', 'Every time I meet my older brother he is taller.', 'authored'),
  ('st-ex-tabini-4', 'sent-ex-tabini-4', 'en', 'Every time it rains the road gets worse.', 'authored')
